def chunkDancing():
    chunk = Find("Chunk")
    if(chunk and G.Chunk_Dominated == 2 and G.Story_State < 10 and G.Chunk_Dead == 0 and not __main__.IsDead("Chunk")):
        chunk.ScriptUnhide()
    else:
        chunk.ScriptHide()
    if G.Danielle_Dead == 1:
        danielle = Find("Danielle")
        if danielle: danielle.Kill()
    if G.Doll1_Dead == 1:
        doll1 = Find("Doll1")
        if doll1: doll1.Kill()

