functions.knoxPresence:
def knoxPresence():
    IsDead = __main__.IsDead
    if (G.Mercurio_Quest >= 2 and not IsDead("Knox")):
        if G.Patch_Plus == 1:
            knox = Find("Knox_plus")
            if knox:
                knox.ScriptUnhide()
                knox.SetName("Knox")
        else:
            knox = Find("Knox_basic")
            if knox:
                knox.ScriptUnhide()
                knox.SetName("Knox")

